  "recipeCuisine": "Italian",
  "recipeIngredient": [
    "50g dried porcini mushrooms",
    "1 vegetable stock cube",
    "2 tbsp olive oil",
    "1 onion finely chopped",
    "2 garlic cloves finely chopped",
    "250g pack chestnut mushrooms chopped",
    "300g risotto rice such as arborio",
    "1 x 175ml glass white wine",
    "25g butter",
    "handful parsley leaves, chopped",
    "50g parmesan or Grana Padano, freshly grated"
  ],
  "recipeInstructions": [
    {
      "@type": "HowToStep",
      "text": "Put 50g dried porcini mushrooms into a large bowl and pour over 1 litre boiling water. Soak for 20 mins, then drain into a bowl, discarding the last few tbsp of liquid left in the bowl."
    },
    {
      "@type": "HowToStep",
      "text": "Crumble 1 vegetable stock cube into the mushroom liquid, then squeeze the mushrooms gently to remove any liquid."
    },
    {
      "@type": "HowToStep",
      "text": "Heat 2 tbsp olive oil in a shallow saucepan or deep frying pan over a medium flame. Add 1 finely chopped onion and 2 finely chopped garlic cloves, then fry for about 5 mins until soft."
    },
    {
      "@type": "HowToStep",
      "text": "Stir in 250g chopped chestnut mushrooms and the dried mushrooms, season with salt and pepper and continue to cook for 8 mins until the fresh mushrooms have softened."
    },
    {
      "@type": "HowToStep",
      "text": "Tip 300g risotto rice into the pan and cook for 1 min. Pour over a 175ml glass of white wine and let it bubble to nothing so the alcohol evaporates."
    },
    {
      "@type": "HowToStep",
      "text": "Keep the pan over a medium heat and pour in a quarter of the mushroom stock. Simmer the rice, stirring often, until the rice has absorbed all the liquid."
    },
    {
      "@type": "HowToStep",
      "text": "Add about the same amount of stock again and continue to simmer and stir - it should start to become creamy, plump and tender. By the time the final quarter of stock is added, the rice should be almost cooked."
    },
    {
      "@type": "HowToStep",
      "text": "Continue stirring until the rice is cooked. If the rice is still undercooked, add a splash of water. Take the pan off the heat, add 25g butter and scatter over 25g grated parmesan or Grana Padano cheese and half a handful of chopped parsley leaves."
    },
    {
      "@type": "HowToStep",
      "text": "Cover and leave for a few mins so that the rice can take up any excess liquid as it cools a bit. Give the risotto a final stir, spoon into bowls and scatter with the remaining 25g grated cheese and the remaining chopped parsley leaves."
    }
  ],
  "recipeYield": 4,
  "totalTime": "PT30M"
}
